import { useEffect, useState, useRef } from "react";
import { Pie, Bar } from "react-chartjs-2";
import "chart.js/auto";
import {
  HiOutlineAcademicCap,
  HiOutlineLightningBolt,
  HiOutlineChartBar,
  HiOutlineClock,
  HiOutlineRefresh,
  HiOutlineShare,
  HiOutlineDownload,
  HiOutlineExclamationCircle,
  HiOutlineCheckCircle,
} from "react-icons/hi";
import jsPDF from "jspdf";
import { fetchMyResult, resetAssessment } from "../../services/resultApi";

const Results = () => {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const reportRef = useRef(null);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchMyResult();
        if (!res || res.locked) {
          setResult(null);
        } else {
          setResult(res);
        }
      } catch {
        setResult(null);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  /* ================= CHART CONFIG ================= */
  const commonOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "bottom",
        labels: { padding: 20, usePointStyle: true, font: { size: 12 } },
      },
      tooltip: { backgroundColor: "#1e293b", padding: 12, bodySpacing: 4 },
    },
  };

  const barOptions = {
    ...commonOptions,
    plugins: { ...commonOptions.plugins, legend: { display: false } },
    scales: {
      y: {
        beginAtZero: true,
        max: 100,
        grid: { display: false },
        ticks: { font: { size: 11 } },
      },
      x: { grid: { display: false }, ticks: { font: { size: 11 } } },
    },
  };

  /* ================= MODERN PDF GENERATION LOGIC ================= */
  const handleDownloadPDF = () => {
    if (!result) return;

    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    const margin = 20;
    const contentWidth = pageWidth - margin * 2;
    let yPos = 0;

    const colors = {
      blue: [37, 99, 235], // #2563eb
      purple: [124, 58, 237], // #7c3aed
      gold: [245, 158, 11], // #f59e0b
      dark: [30, 41, 59], // Slate 800
      lightGray: [241, 245, 249],
      border: [226, 232, 240],
    };

    // Increased Logo Size Placeholder
    const logoBase64 =
      "data:image/png;base64,";

    // Helper: Light Header Design
    const drawHeader = () => {
      // Light background for header area
      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, pageWidth, 50, "F");
      doc.setDrawColor(colors.border[0], colors.border[1], colors.border[2]);
      doc.line(0, 50, pageWidth, 50);

      // Increased Logo Size (30x30)
      try {
        doc.addImage(logoBase64, "PNG", margin, 10, 30, 30);
      } catch (e) {
        console.warn("Logo load failed");
      }

      // Header Text with Color Accents
      doc.setTextColor(colors.dark[0], colors.dark[1], colors.dark[2]);
      doc.setFontSize(22);
      doc.setFont("helvetica", "bold");
      doc.text("CAREER FITMENT REPORT", margin + 35, 24);

      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(colors.purple[0], colors.purple[1], colors.purple[2]);
      doc.text("AI-DRIVEN COMPETENCY & DOMAIN INSIGHTS", margin + 35, 30);
    };

    const addWrappedText = (
      text,
      fontSize = 11,
      style = "normal",
      color = colors.dark,
    ) => {
      doc.setFontSize(fontSize);
      doc.setFont("helvetica", style);
      doc.setTextColor(color[0], color[1], color[2]);
      const lines = doc.splitTextToSize(
        text || "Information not available",
        contentWidth - 10,
      );

      if (yPos + lines.length * 6 > 280) {
        doc.addPage();
        yPos = 30;
      }
      doc.text(lines, margin + 5, yPos);
      yPos += lines.length * (fontSize / 1.8) + 4;
    };

    const drawSectionTitle = (title, accentColor) => {
      yPos += 12;
      doc.setFillColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.rect(margin, yPos - 5, contentWidth, 8, "F"); // Full width light bar

      doc.setFontSize(11);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(255, 255, 255);
      doc.text(title.toUpperCase(), margin + 5, yPos + 1);
      yPos += 10;
    };

    // --- Start Generation ---
    drawHeader();
    yPos = 65;

    // 1. PROFILE CARD
    doc.setFillColor(
      colors.lightGray[0],
      colors.lightGray[1],
      colors.lightGray[2],
    );
    doc.roundedRect(margin, yPos - 5, contentWidth, 35, 2, 2, "F");

    doc.setTextColor(colors.blue[0], colors.blue[1], colors.blue[2]);
    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text(result.studentName || "User Name", margin + 8, yPos + 5);

    doc.setTextColor(colors.dark[0], colors.dark[1], colors.dark[2]);
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text(`Email: ${result.studentEmail || "N/A"}`, margin + 8, yPos + 12);
    doc.text(`Target Domain: ${result.targetDomain}`, margin + 8, yPos + 19);
    doc.text(`Level: ${result.educationLevel}`, margin + 8, yPos + 26);
    yPos += 45;

    // 2. DETAILED ANALYSIS
    drawSectionTitle("Assessment Reasoning", colors.purple);
    addWrappedText(result.fitReasoning);

    drawSectionTitle("Identified Skill Gaps", colors.gold);
    addWrappedText(result.gapReasoning);

    // 3. PERFORMANCE CHART SIMULATION
    drawSectionTitle("Metric Breakdown", colors.blue);
    (result.categoryScores || []).forEach((cat) => {
      if (yPos > 270) {
        doc.addPage();
        yPos = 30;
      }

      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(colors.dark[0], colors.dark[1], colors.dark[2]);

      // Text Label
      doc.text(cat.category, margin + 5, yPos);

      // Progress track (Background)
      doc.setFillColor(235, 235, 240);
      doc.roundedRect(margin + 70, yPos - 3, 80, 3, 1, 1, "F");

      // Progress fill (Purple)
      doc.setFillColor(colors.purple[0], colors.purple[1], colors.purple[2]);
      const barWidth = (cat.percentage / 100) * 80;
      doc.roundedRect(margin + 70, yPos - 3, barWidth, 3, 1, 1, "F");

      // Percentage Label (Right Aligned)
      doc.setTextColor(colors.purple[0], colors.purple[1], colors.purple[2]);
      doc.text(`${cat.percentage}%`, margin + 155, yPos);

      yPos += 10; // Consistent vertical spacing between bars
    });

    // 4. NEXT STEPS
    drawSectionTitle("Career Recommendations", colors.purple);
    addWrappedText(
      `Recommended Roles: ${(result.recommendedCareers || []).join(" • ")}`,
      11,
      "bold",
      colors.blue,
    );

    yPos += 6;
    const bulletGutter = 12; // The horizontal space reserved for the bullet

    (result.improvementSuggestions || []).forEach((tip) => {
      // 1. Calculate the lines for this specific tip to handle wrapping correctly
      const textLines = doc.splitTextToSize(tip, contentWidth - bulletGutter);

      // 2. Page overflow check
      if (yPos + textLines.length * 6 > 280) {
        doc.addPage();
        yPos = 30;
      }

      // 3. Draw the bullet point
      // We align it with the vertical center of the first line (approx yPos + 1.5)
      doc.setFillColor(colors.gold[0], colors.gold[1], colors.gold[2]);
      doc.circle(margin + 6, yPos + 1.5, 0.8, "F");

      // 4. Draw the text
      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(80, 80, 80);

      // Use the gutter to indent the text so it doesn't overlap the bullet
      doc.text(textLines, margin + bulletGutter, yPos + 2.5);

      // 5. Update yPos based on the actual height of the text lines drawn
      // 5.5 is the line height, 4 is the paragraph spacing
      yPos += textLines.length * 5.5 + 4;
    });

    // Footer
    const pageCount = doc.internal.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(180);
      doc.text(
        `Page ${i} of ${pageCount} | ${result.studentName} | Career Fitment Report`,
        pageWidth / 2,
        288,
        { align: "center" },
      );
    }

    doc.save(`Career_Report_${result.targetDomain}.pdf`);
  };

  /* ================= ACTION HANDLERS ================= */
  const handleShare = async () => {
    const shareData = {
      title: "My Career Assessment Results",
      text: `I evaluated my fit for ${result.targetDomain}. I scored ${result.overallPercentage}%!`,
      url: window.location.href,
    };
    try {
      if (navigator.share) await navigator.share(shareData);
      else {
        navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.error("Error sharing:", err);
    }
  };

  const handleRetake = async () => {
    if (
      window.confirm(
        "This will permanently delete this result and let you choose a new target domain. Continue?",
      )
    ) {
      try {
        await resetAssessment();
        window.location.href = "/dashboard";
      } catch (err) {
        alert("Failed to reset assessment.");
      }
    }
  };

  if (loading)
    return (
      <div className="flex min-h-screen items-center justify-center bg-bg-light">
        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );

  if (!result)
    return (
      <div className="flex min-h-screen items-center justify-center bg-bg-light text-slate-500 font-medium">
        No results found. Complete an assessment to see analytics.
      </div>
    );

  const categoryScores = Array.isArray(result.categoryScores)
    ? result.categoryScores
    : [];
  const chartData = {
    labels: categoryScores.map((c) => c.category),
    datasets: [
      {
        label: "Mastery %",
        data: categoryScores.map((c) => c.percentage),
        backgroundColor: [
          "#2563eb",
          "#7c3aed",
          "#f59e0b",
          "#10b981",
          "#ef4444",
        ],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="min-h-screen bg-bg-light pt-8 pb-32 font-sans px-4">
      <div className="max-w-5xl mx-auto">
        <div
          className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 p-6 md:p-10 relative overflow-hidden"
          ref={reportRef}
        >
          {/* Header */}
          <div className="text-center mb-12 relative z-10">
            <div className="inline-flex items-center justify-center p-3 bg-indigo-50 rounded-2xl mb-4 text-indigo-600">
              <HiOutlineChartBar className="text-3xl" />
            </div>
            <h2 className="text-3xl md:text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-violet-600 mb-2">
              Fitment: {result.targetDomain}
            </h2>
            <p className="text-slate-500 font-medium bg-slate-100 inline-block px-4 py-1 rounded-full text-sm">
              Level: {result.educationLevel}
            </p>
          </div>

          {/* Analysis Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-12">
            <div className="bg-emerald-50/50 rounded-2xl p-6 border border-emerald-100 flex gap-4 transition-transform hover:scale-[1.01]">
              <HiOutlineCheckCircle className="text-3xl text-emerald-500 shrink-0" />
              <div>
                <h4 className="font-bold text-emerald-900 mb-2">Why You Fit</h4>
                <p className="text-emerald-700/80 text-sm leading-relaxed">
                  {result.fitReasoning ||
                    "Your strengths align with the core requirements of this field."}
                </p>
              </div>
            </div>

            <div className="bg-amber-50/50 rounded-2xl p-6 border border-amber-100 flex gap-4 transition-transform hover:scale-[1.01]">
              <HiOutlineExclamationCircle className="text-3xl text-amber-500 shrink-0" />
              <div>
                <h4 className="font-bold text-amber-900 mb-2">
                  Potential Gaps
                </h4>
                <p className="text-amber-700/80 text-sm leading-relaxed">
                  {result.gapReasoning ||
                    "Focus on the categories listed below to bridge the skill gap."}
                </p>
              </div>
            </div>
          </div>

          {/* Charts */}
          {categoryScores.length > 0 && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-12">
              <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 relative h-80 flex flex-col">
                <h4 className="text-slate-900 font-bold mb-4 text-sm uppercase tracking-wider text-center">
                  Distribution
                </h4>
                <div className="flex-1 relative w-full h-full min-h-0">
                  <Pie
                    data={chartData}
                    options={{ ...commonOptions, maintainAspectRatio: false }}
                  />
                </div>
              </div>
              <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 relative h-80 flex flex-col">
                <h4 className="text-slate-900 font-bold mb-4 text-sm uppercase tracking-wider text-center">
                  Category Performance
                </h4>
                <div className="flex-1 relative w-full h-full min-h-0">
                  <Bar
                    data={chartData}
                    options={{ ...barOptions, maintainAspectRatio: false }}
                  />
                </div>
              </div>
            </div>
          )}

          {/* Insights Columns */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
            <section>
              <h3 className="flex items-center gap-2 font-bold text-slate-800 mb-4 text-lg">
                <HiOutlineLightningBolt className="text-indigo-500" />{" "}
                Identified Strengths
              </h3>
              <ul className="space-y-3">
                {(result.strengths || []).map((s, idx) => (
                  <li
                    key={idx}
                    className="flex items-start gap-3 text-slate-600 bg-white p-3 rounded-xl border border-slate-100 shadow-sm"
                  >
                    <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 mt-2 shrink-0"></span>
                    <span className="text-sm">{s}</span>
                  </li>
                ))}
              </ul>
            </section>

            <section>
              <h3 className="flex items-center gap-2 font-bold text-slate-800 mb-4 text-lg">
                <HiOutlineAcademicCap className="text-amber-500" /> Alternative
                Career Options
              </h3>
              <ul className="space-y-3">
                {(result.recommendedCareers || []).map((c, idx) => (
                  <li
                    key={idx}
                    className="flex items-start gap-3 text-slate-600 bg-white p-3 rounded-xl border border-slate-100 shadow-sm"
                  >
                    <span className="w-1.5 h-1.5 rounded-full bg-amber-500 mt-2 shrink-0"></span>
                    <span className="text-sm">{c}</span>
                  </li>
                ))}
              </ul>
            </section>
          </div>

          {/* Score Summary */}
          <div className="border-t border-slate-100 pt-10 mt-8 text-center bg-slate-50/50 rounded-2xl p-8">
            <div className="flex justify-center items-center gap-2 text-slate-400 text-sm font-medium mb-2">
              <HiOutlineClock />
              <span>
                Assessment Duration: {Math.floor(result.timeSpent / 60)}m{" "}
                {result.timeSpent % 60}s
              </span>
            </div>
            <p className="text-slate-600 font-medium mb-1">
              Overall Readiness Score
            </p>
            <strong className="text-5xl md:text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-emerald-500 to-teal-500 tracking-tight">
              {result.overallPercentage || 0}%
            </strong>
          </div>
        </div>
      </div>

      {/* Floating Action Bar */}
      <div className="fixed bottom-6 left-4 right-4 md:left-1/2 md:right-auto md:-translate-x-1/2 flex items-center justify-between md:justify-center gap-2 md:gap-4 bg-white/90 backdrop-blur-xl p-3 rounded-2xl shadow-2xl border border-slate-200/60 z-50">
        <button
          onClick={handleRetake}
          className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2.5 rounded-xl font-bold text-slate-600 hover:bg-slate-100 hover:text-slate-900 transition-colors text-xs md:text-sm"
        >
          <HiOutlineRefresh className="text-lg md:text-xl" />
          <span className="hidden sm:inline">Recalibrate</span>
        </button>

        <div className="w-px h-6 bg-slate-200"></div>

        <button
          onClick={handleShare}
          className="flex items-center gap-2 px-3 py-2 md:px-4 md:py-2.5 rounded-xl font-bold text-slate-600 hover:bg-slate-100 hover:text-slate-900 transition-colors text-xs md:text-sm"
        >
          <HiOutlineShare className="text-lg md:text-xl" />
          <span className="hidden sm:inline">Share</span>
        </button>

        <button
          onClick={handleDownloadPDF}
          className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-3 md:px-6 md:py-2.5 rounded-xl font-bold text-white bg-slate-900 hover:bg-black shadow-lg shadow-slate-200 hover:scale-105 transition-all text-xs md:text-sm ml-1"
        >
          <HiOutlineDownload className="text-lg" />
          <span>
            Download <span className="hidden sm:inline">Report</span>
          </span>
        </button>
      </div>
    </div>
  );
};

export default Results;
